/**
 * All the logos as one SVG sprite of <symbol>s, served (and cached) at /_assets/services.svg so
 * the page itself stays small. Brand colors are drawn in: the CSP allows no inline styles.
 */
export const SERVICES_SPRITE = `<svg xmlns="http://www.w3.org/2000/svg">${SERVICE_ICONS.map(
  ([, color, ink, path], i) =>
    `<symbol id="svc-${i}" viewBox="0 0 48 48"><rect width="48" height="48" rx="12" fill="${color}"/><path transform="translate(12 12)" fill="${ink}" d="${path}"/></symbol>`,
).join("")}</svg>`;

export const SPRITE_URL = `/_assets/services.svg?n=${SERVICE_ICONS.length}`;
